package io.knowledgebrain.notification;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import io.knowledgebrain.contracts.collaboration.submissionfeedback.v1.*;import io.knowledgebrain.contracts.collaboration.resubmissionrequest.v1.*;import io.knowledgebrain.contracts.collaboration.submissiongrade.v1.*;
class ReviewSignalTest {
 GroupReviewStore.Access a=new GroupReviewStore.Access(ReviewFixtures.ids.next(),ReviewFixtures.ids.next(),ReviewFixtures.ids.next(),1);
 @Test void stripsContentAndValidatesMetadataAndTransport()throws Exception{var bytes=ReviewFixtures.feedback(a,1000);var s=ReviewSignal.decode(ReviewSignal.TOPICS.getFirst(),bytes);assertFalse(s.toString().contains("PRIVATE OPINION"));assertEquals(ReviewSignal.hash(bytes),s.payloadHash());var headers=new HashMap<>(Map.of("id",s.eventId().toString(),"trace_id",ReviewFixtures.trace,"schema_group","collaboration","schema_artifact","submission-feedback-events","schema_version","1"));ReviewSignal.transport(ReviewSignal.TOPICS.getFirst(),s.aggregateId().toString(),headers,bytes);headers.put("schema_artifact","submission-grade-events");assertThrows(IllegalArgumentException.class,()->ReviewSignal.transport(ReviewSignal.TOPICS.getFirst(),s.aggregateId().toString(),headers,bytes));var e=SubmissionFeedbackEnvelopeV1.parseFrom(bytes);for(var bad:List.of(e.toBuilder().setProducer("knowledge-service").build(),e.toBuilder().setSpaceId(ReviewFixtures.ids.next().toString()).build(),e.toBuilder().setActorId(a.principalId().toString()).build(),e.toBuilder().setOccurredAtEpochMillis(1001).build(),e.toBuilder().setEventVersion(2).build()))assertThrows(IllegalArgumentException.class,()->ReviewSignal.decode(ReviewSignal.TOPICS.getFirst(),bad.toByteArray()));}
 @Test void gradeAndResubmissionProjectOnlyMinimalReferences()throws Exception{var e=SubmissionFeedbackEnvelopeV1.parseFrom(ReviewFixtures.feedback(a,1000));var f=SubmissionFeedbackSnapshotV1.parseFrom(e.getPayload());var g=SubmissionGradeSnapshotV1.newBuilder().setGradeId(f.getFeedbackId()).setSubmissionId(f.getSubmissionId()).setAssignmentId(f.getAssignmentId()).setStudyId(f.getStudyId()).setGroupId(f.getGroupId()).setSpaceId(f.getSpaceId()).setAuthorId(f.getAuthorId()).setGraderId(f.getReviewerId()).setVersion(1).setSubmissionVersion(1).setAssignmentVersion(2).setReason("secret score reason").setAudience("AUTHOR_AND_OWNER").setScore(100).setCreatedAt(f.getCreatedAt()).setUpdatedAt(f.getUpdatedAt()).build();var ge=SubmissionGradeEnvelopeV1.parseFrom(e.toByteArray()).toBuilder().setAggregateType("SubmissionGrade").setEventType("SubmissionGradeRecorded").setPayload(g.toByteString()).build();assertEquals("GRADE",ReviewSignal.decode(ReviewSignal.TOPICS.get(2),ge.toByteArray()).kind());assertThrows(IllegalArgumentException.class,()->ReviewSignal.decode(ReviewSignal.TOPICS.get(2),ge.toBuilder().setPayload(g.toBuilder().setScore(101).build().toByteString()).build().toByteArray()));var p=ResubmissionRequestSnapshotV1.newBuilder().setRequestId(f.getFeedbackId()).setSubmissionId(f.getSubmissionId()).setAssignmentId(f.getAssignmentId()).setStudyId(f.getStudyId()).setGroupId(f.getGroupId()).setSpaceId(f.getSpaceId()).setAuthorId(f.getAuthorId()).setChangedBy(f.getReviewerId()).setRequestedBy(f.getReviewerId()).setVersion(1).setSubmissionVersion(1).setAssignmentVersion(2).setReason("secret request reason").setAudience("AUTHOR_AND_OWNER").setState("REQUESTED").setCreatedAt(f.getCreatedAt()).setUpdatedAt(f.getUpdatedAt()).build();var re=ResubmissionRequestEnvelopeV1.parseFrom(e.toByteArray()).toBuilder().setAggregateType("ResubmissionRequest").setEventType("ResubmissionRequested").setPayload(p.toByteString()).build();assertEquals("RESUBMISSION_REQUESTED",ReviewSignal.decode(ReviewSignal.TOPICS.get(1),re.toByteArray()).kind());assertFalse(ReviewSignal.decode(ReviewSignal.TOPICS.get(1),re.toByteArray()).toString().contains("secret request"));}
 @Test void recoveryRejectsOffsetsOutsideRetainedRange(){assertTrue(GroupReviewConsumer.gap(null,1,10));assertTrue(GroupReviewConsumer.gap(0L,1,10));assertTrue(GroupReviewConsumer.gap(11L,1,10));assertFalse(GroupReviewConsumer.gap(10L,1,10));assertFalse(GroupReviewConsumer.gap(null,0,10));}
}
